// TH18 v1.00a Stage 6 MainSub04 / GirlA05.
// Source st06.ecl.txt:1277-1289 (MainSub04), 660-679 (GirlA05), 681-729 (GirlA05_at).
// Source local wave clock: mirror pair at 0,60,120,180,240; MainSub04 returns at 300.
// Training shell: 120-frame buffer before the first pair; source pair schedule then runs intact.

const TIME_LIMIT: int = 1300;      // 120 buffer + 1180 frames from first pair (cull + tail)
const OPENING_BUFFER: int = 120;
const TH18_BALL2: int = 432;       // TH18 type 5 row base; color 13 kept from etSprite(0,5,13)

xformdef GIRL_RUSH {
    // EX 701 type 0x80000000 WAIT a=20, then EX 702 type 0x200000 VELTIME
    // a=100, r=3.2, s=-9999994 (keep effect-entry angle). Direction stays fixed.
    wait(20);
    step_speed(3.2fx, 100 + 65536 * EASE_LINEAR);
}

async sub girl_shot() {
    wait(10);                      // source GirlA05_at: wait(10) before etNew
    var rank: int = global(GVAR_RANK);
    var tail: int = 160;           // source !E 160 / !N 80 / !H 80 / !LO 60
    if rank == 1 { tail = 80; }
    if rank == 2 { tail = 80; }
    if rank == 3 { tail = 60; }
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, 13);  // etSprite(0,5,13); type5 base radius 4
    sh_count(0, 1, 1);
    sh_aim(0, 0);
    sh_speed(0, 0.5fx, 0fx);       // etSpeed(0,0.5,1.0), one layer -> first speed 0.5
    sh_dist(0, -2fx);              // ANIM a=1: -4*initial speed = -2px along own angle
    sh_xform(0, GIRL_RUSH);
    for vol in 0..10 {             // source $A = 10
        for shot in 0..10 {        // source $B = 10
            // etOffsetRad(0,RANDRAD,RANDF2*32), then etAngle(0,RANDF2*2deg,60deg).
            // RANDF2 is signed [-1,1); draw order preserved per shot.
            var ua: int = rand(65536);
            var ur: int = rand(65536) - 32768;
            var dist: fx = ((ur as fx) / 32768) * 32fx;
            var uj: fx = ((rand(65536) - 32768) as fx) / 32768;
            sh_offset_rad(0, (ua as angle), dist);
            sh_angle(0, aim_player() + ((364fx * uj) as int as angle), 0deg);
            sh_fire(0);
            wait(2);
        }
        wait(tail);
    }
}

async sub girl(side: int) {
    // Source GirlA05 entry: setHurtbox(24,24), setHitbox(16,16), invulnerable practice.
    set_hurtbox(12fx);
    set_hitbox(8fx);
    set_invuln(65535);
    // Source moveVel(-1.1780972,1.4) = -67.5deg; enmCreateM mirrors the right-hand twin.
    var dir: angle = -67.5deg;
    var turn: angle = 1deg;
    if side == 1 { dir = -112.5deg; turn = -1deg; }
    move_vel(0, dir, 1.4fx, EASE_LINEAR);
    spawn girl_shot();
    wait(120);                     // source wait(120) before moveVelTime
    // Source moveVelTime(360,7,0.017453292,0.0): +1deg/frame, speed delta 0.
    // Explicit per-frame polar set preserves the full 360-degree turn and the
    // constant 1.4 speed (radius v/omega ~ 80.2px).
    var a: angle = dir;
    for i in 0..360 {
        a = a + turn;
        move_vel(0, a, 1.4fx, EASE_LINEAR);
        wait(1);
    }
    loop { wait(1000); }
}

async sub wave() {
    wait(OPENING_BUFFER);
    for round in 0..5 {
        // Source MainSub04: enmCreate(-224,360) and enmCreateM(224,360), then wait(60).
        _ = spawn_enemy(-224fx, 360fx, 500, 0, 1000, 1, girl(0));
        _ = spawn_enemy(224fx, 360fx, 500, 0, 1000, 1, girl(1));
        wait(60);
    }
}

async sub encounter() {
    // Training-only phase owner at (0,0); no source body collision.
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
